import sys

def is_prime(n):
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True

def main():
    d = sys.stdin.read().split()
    q = int(d[0])
    print('\n'.join('YES' if is_prime(int(x)) else 'NO' for x in d[1:1 + q]))

main()

